import{_ as a,H as t,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"14 | 预案场景（一）：B站最为深刻的一次自我剖析","description":"","frontmatter":{},"headers":[{"level":2,"title":"故障回顾","slug":"故障回顾","link":"#故障回顾","children":[]},{"level":2,"title":"故障分析","slug":"故障分析","link":"#故障分析","children":[]},{"level":2,"title":"故障优化","slug":"故障优化","link":"#故障优化","children":[{"level":3,"title":"核心点一：双活与切流","slug":"核心点一-双活与切流","link":"#核心点一-双活与切流","children":[]},{"level":3,"title":"核心点二：故障演练","slug":"核心点二-故障演练","link":"#核心点二-故障演练","children":[]},{"level":3,"title":"核心点三：隔离和解耦","slug":"核心点三-隔离和解耦","link":"#核心点三-隔离和解耦","children":[]},{"level":3,"title":"核心点四：应对故障恢复之后的流量","slug":"核心点四-应对故障恢复之后的流量","link":"#核心点四-应对故障恢复之后的流量","children":[]},{"level":3,"title":"核心点五：基础服务要做严格的测试","slug":"核心点五-基础服务要做严格的测试","link":"#核心点五-基础服务要做严格的测试","children":[]},{"level":3,"title":"核心点六：应急响应","slug":"核心点六-应急响应","link":"#核心点六-应急响应","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SRE实践：服务可靠性案例课/14｜预案场景（一）：B站最为深刻的一次自我剖析.md","filePath":"SRE实践：服务可靠性案例课/14｜预案场景（一）：B站最为深刻的一次自我剖析.md","lastUpdated":1795534831000}'),E={name:"SRE实践：服务可靠性案例课/14｜预案场景（一）：B站最为深刻的一次自我剖析.md"};function n(r,e,s,p,o,h){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_14-预案场景-一-b站最为深刻的一次自我剖析" tabindex="-1">14 | 预案场景（一）：B站最为深刻的一次自我剖析 <a class="header-anchor" href="#_14-预案场景-一-b站最为深刻的一次自我剖析" aria-label="Permalink to &quot;14 | 预案场景（一）：B站最为深刻的一次自我剖析&quot;">​</a></h1><p>你好，我是白园。</p><p>今天我们开始进入预案场景故障的分析。这节课我们就来分析一下 B 站 2021 年 7 月 13 日的故障这也是我见过的公司对自身故障剖析得最详细的一次，我们来看看能从中学习到什么内容。</p><h2 id="故障回顾" tabindex="-1">故障回顾 <a class="header-anchor" href="#故障回顾" aria-label="Permalink to &quot;故障回顾&quot;">​</a></h2><p>7 月 13 日 23 时许，B 站客户端和网页端均出现访问故障，无法打开，页面提示“正在玩命加载数据”。不久后，“B 站崩了”话题也迅速登上微博热搜。14 日凌晨 B 站网页端和 App 才恢复正常。</p><p>22:52 是故障开始的时间，SRE 团队接到了关于服务和域名接入层不可用的多起警报。与此同时，客服部门接到了大量用户反映 B 站无法访问的反馈，公司内部员工也报告了相同的问题，包括 App 首页加载失败。根据报警信息，SRE 团队迅速把注意力集中在可能的基础设施故障上，包括数据中心、网络连接、四层负载均衡器（L4 LB）和七层负载均衡器（L7SLB）。为了迅速应对，SRE 团队立即启动了紧急语音会议，并召集了所有相关团队的成员进行紧急处理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/1.png" alt=""></a></p><p>故障原因：7 层接入 SLB 代码 BugB 站在 2019 年 9 月份，迁移到了 OpenResty，通过服务在注册中心的权重变更，来实现SLB 的动态调权，从而实现更精细的灰度能力。在某种发布模式中，应用的实例权重会短暂地调整为 0，这个时候注册中心返回给 SLB 的权重是字符串类型的 0。这个时候由于 lua 语言的特性并不会强制转化字符串的 0 为数字 0，程序就会陷入到死循环进而把 worker 打死。</p><p>根因分析</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/2.png" alt=""></a></p><ul><li>Lua 是动态类型语言，常用习惯里变量不需要定义类型，只需要为变量赋值即可。Lua 在对一个数字字符串进行算术操作时，会尝试将这个数字字符串转成一个数字。在 Lua 语言中，如果执行数学运算 n % 0，则结果会变为 nan（Not A Number）。_gcd 函数对入参没有做类型校验，允许参数 b 传入：“0”。同时因为&quot;0&quot; != 0，所以此函数第一次执行后返回是 _gcd(“0”,nan)。如果传入的是 int 0，则会触发[ if b == 0 ]分支逻辑判断，不会死循环。_gcd(“0”,nan) 函数再次执行时返回值是 _gcd(nan,nan)，然后 Nginx worker 开始陷入死循环，进程 CPU 100%。</li></ul><p>这里的根因分析你了解就可以了，如果你有兴趣可以直接看当时 B 站发布的报告。而我们这节课的重点是发现这个案例中的问题，并讨论优化策略。接下来我们先分析一下这次故障里的几个关键点。</p><h2 id="故障分析" tabindex="-1">故障分析 <a class="header-anchor" href="#故障分析" aria-label="Permalink to &quot;故障分析&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/3.png" alt=""></a></p><p>首先是响应时间，用了 3 分钟，还是非常快的。那是否可以再加加速呢？理论上来说比较难，这里就不再重点讨论。</p><p>其次是准备时间，用时 22 分钟，这段时间我们看到 B 站做的最重要的操作就是了解如何通过绿色通道登录内网系统。这段时间暴露了两个问题，第一个是内网鉴权系统和接入层的循环依赖，第二个是如何通过绿色通道登录机器，就是日常紧急情况的演练和覆盖的缺失。</p><p>故障恢复过程历时 110 分钟，从 00:00 开始至 01:50 结束。在这段时间内，SLB 新集群的搭建工作耗时 60 分钟，包括集群的搭建、初始化、负载均衡配置以及公网 IP 的分配。随后的50 分钟内，团队开始逐步切换流量至新集群。</p><p>在多活业务的恢复方面，SLB 运维团队发现多活机房的 SLB 存在大量请求超时的问题，但幸运的是，CPU 并未出现过载的情况。因此，团队决定先重启多活机房的 SLB，以尝试控制问题的扩散。在重启操作进行时，内部群组中的同学报告称主站服务已经恢复。进一步观察多活机房 SLB 的监控数据，发现请求超时的数量显著减少，业务成功率回升至 50% 以上。随着这些措施的实施，多活业务的核心功能，包括 App 推荐、播放、评论与弹幕拉取、动态更新、追番以及影视观看等，已基本恢复正常。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/4.png" alt=""></a></p><p>这里我们可以回顾一下 B 站几个有效的止损动作。全程时间 178 分钟，一是登录内网用时 22分钟。二是无效尝试重启用时 30 分钟。三是服务搭建用时 60 分钟。四是服务切流用时 50 分钟。</p><h2 id="故障优化" tabindex="-1">故障优化 <a class="header-anchor" href="#故障优化" aria-label="Permalink to &quot;故障优化&quot;">​</a></h2><h3 id="核心点一-双活与切流" tabindex="-1">核心点一：双活与切流 <a class="header-anchor" href="#核心点一-双活与切流" aria-label="Permalink to &quot;核心点一：双活与切流&quot;">​</a></h3><p>在本次故障中，实现业务快速恢复的关键策略是双活部署和流量切换。如果所有业务能够在故障发生后立即执行流量切换，理论上所有业务可以在 23:23 分恢复。所以当面对极端故障的时候双活和切流是最为重要的手段，一定要严格地进行双活建设和服务逃生。通过有效的切换措施，故障时间从 178 分钟显著缩短至 31 分钟。</p><p>但是还有很多服务没有恢复，这其中也暴露了一些问题，这些问题也是在多活建设中很常见的。</p><ol><li><p>机房和业务混乱：机房与业务的多活定位关系不明确，CDN 多机房流量调度不支持固定路由和分片，业务多活架构在写入功能上存在缺陷，导致当时未能完全恢复。</p></li><li><p>元信息管理缺失：缺乏一个统一的平台来管理哪些业务实现了多活，以及它们是采用同城双活还是异地单元化的策略。此外，也不清楚哪些 URL 规则支持多活，以及当前的多活流量调度策略是什么，这些信息目前只能通过文档临时维护。</p></li><li><p>切流缓慢：多活切操作高度依赖 CDN 团队执行，其他人员没有操作权限，导致效率低下。缺少切量管理平台，使整个切量过程缺乏透明度。接入层和存储层的切量操作分离，无法实现有效编排。由于缺乏业务多活元信息，切量的准确性和容灾效果受到影响。</p></li></ol><p>关于如何做双活和逃生，我们会在下一讲中介绍。</p><h3 id="核心点二-故障演练" tabindex="-1">核心点二：故障演练 <a class="header-anchor" href="#核心点二-故障演练" aria-label="Permalink to &quot;核心点二：故障演练&quot;">​</a></h3><p>B 站在做重建的时候还是非常慢的，主要原因在于多个团队操作，日常缺乏演练，必然会导致各种各样的问题。SLB 的预案中只演练过 SLB 机器初始化、配置初始化，但和四层 LB 公网IP 配置、CDN 之间的协作并没有做过全链路演练，元信息在平台之间也没有联动，比如四层LB 的 Real Server 信息提供、公网运营商线路、CDN 回源 IP 的更新等。所以一次完整的新建源站耗时非常久。</p><p>每个团队分工不同，这里我们先不考虑平台化的事情，我们先考虑人是否可以通过配合来加速。多个团队相互配合的快速重建的演练，重要性不言而喻。只有通过反复练习，才能有效提升速度。</p><h3 id="核心点三-隔离和解耦" tabindex="-1">核心点三：隔离和解耦 <a class="header-anchor" href="#核心点三-隔离和解耦" aria-label="Permalink to &quot;核心点三：隔离和解耦&quot;">​</a></h3><p>B 站在复盘的时候发现，用户在登录内网鉴权系统时，鉴权系统会跳转到多个域名下，其中一个域名是由故障的 SLB 代理的，受 SLB 故障影响，当时此域名无法处理请求，导致用户登录失败。</p><p>循环依赖在系统架构中是一个普遍存在的问题，一旦出现故障，可能会导致整个系统无法正常运作。因此，在制定日常的预案演练时，必须特别关注循环依赖的问题，并采取措施进行解耦。我们来了解几个常见的解耦策略。</p><ul><li><p>内网与外网接入的解耦：在故障发生前，单一的 SLB 可能会成为故障域隔离的瓶颈。为了避免这种情况，建议将 SLB 按业务部门进行拆分，为每个核心业务部门配置独立的 SLB 集群和公网 IP 地址，以实现更有效的故障隔离和管理。</p></li><li><p>预案与基础服务的解耦：预案平台和基础服务之间不应存在循环依赖。例如，数据库切换操作如果依赖于预案平台，而预案平台又依赖于数据库来存储预案信息，这将形成一个恶性循环。我们应该设计一种机制，使预案平台和数据库之间能够独立运作，而不是相互依赖。</p></li><li><p>建立绿色通道：在系统设计中应包含绿色通道机制，以便在紧急情况下快速恢复关键服务，如用户登录等。</p></li><li><p>机房外部的带外系统：除了机房内部的处理系统外，还应该建立一个带外系统，即独立于主系统之外的备用管理系统，用于在主系统不可用时进行故障处理和恢复操作。</p></li></ul><h3 id="核心点四-应对故障恢复之后的流量" tabindex="-1">核心点四：应对故障恢复之后的流量 <a class="header-anchor" href="#核心点四-应对故障恢复之后的流量" aria-label="Permalink to &quot;核心点四：应对故障恢复之后的流量&quot;">​</a></h3><p>在故障期间，多活 SLB 面临了极大的压力，主要由于 CDN 流量的回源重试以及用户端的频繁重试行为，这导致流量剧烈增加，超过了正常水平的四倍。同时，连接数激增到 1000 万的量级，最终引起了 SLB 的过载。</p><p>尽管如此，随着流量的自然回落和 SLB 的及时重启，服务开始逐步恢复到正常状态。在常规的晚高峰时段，这个 SLB 集群的 CPU 使用率一般维持在 30% 左右，并且拥有接近两倍的额外处理能力。这表明，如果多活 SLB 具备足够的容量，理论上它能够应对流量的突增，从而迅速恢复多活业务。这一情况也凸显了在面临极端故障时，流量管理的重要性以及确保容量充足的必要性。</p><p>为了提高系统在类似情况下的韧性，我们可以进行更细致的容量规划，确保在极端情况下，SLB 能够处理预期之外的流量激增。然后实施有效的流量控制机制，限流同时保持足够的冗余等等，减轻对 SLB 的压力。此外还可以改进系统设计，优化 CDN 和用户端的重试策略，减少不必要的流量和连接数。最后也要加强实时监控系统，以便在流量异常增加时，能够及时发出预警，并采取相应的措施。</p><h3 id="核心点五-基础服务要做严格的测试" tabindex="-1">核心点五：基础服务要做严格的测试 <a class="header-anchor" href="#核心点五-基础服务要做严格的测试" aria-label="Permalink to &quot;核心点五：基础服务要做严格的测试&quot;">​</a></h3><p>对于许多公司的基础服务而言，专业的测试人员并不常见。基础测试往往难度较大，而且执行频率较低，这导致招聘专业测试人员的性价比不高。因此，我建议引入一个专门负责基础组件测试的团队，对 SLB（Server Load Balancer）这样的服务进行全面的异常测试。</p><p>如果无法引入这样的专业测试团队，开发和运维人员就需要学习并掌握必要的测试流程。此外，还应该确保单元测试的覆盖率达到标准。</p><h3 id="核心点六-应急响应" tabindex="-1">核心点六：应急响应 <a class="header-anchor" href="#核心点六-应急响应" aria-label="Permalink to &quot;核心点六：应急响应&quot;">​</a></h3><p>B 站目前还没有建立一个专门的技术支持团队来应对紧急事故。在紧急事故发生时，SRE 工程师不仅要负责故障处理，还要承担故障响应、通报和协同工作。这种做法在处理普通事故时或许可行，但在面对重大事故时，信息同步的速度往往跟不上需求。</p><p>这里阐述一下我的见解，拥有一个专门的团队无疑是理想的，但如果缺乏这样的支持，那么培养 SRE 人员的组织协调能力至关重要。同时，构建一个既完善又简洁的运作机制也非常重要。这包括迅速通报情况，及时召集相关人员；确保关键人员能够迅速了解情况，比如团队领导、对外运营、公关或政府关系人员等等；快速同步目前事件的影响范围和具体情况。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>B 站的故障其实非常典型，其中有非常多的问题值得我们去思考和探索。这里面最关键的双活建设、故障演练、隔离和解耦、严格的测试和发布流程，以及应急响应，都是值得我们去思考和学习的。我这里整理出了一张示意图，你可以结合示意图来复习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/14/5.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你有什么办法在不影响线上服务的同时进行大规模的故障演练，同时能讲清楚收益获得老板的支持？欢迎你把你的答案分享到评论区，也欢迎你把这节课的内容分享给其他朋友，我们下节课再见！</p>',48)])])}const c=a(E,[["render",n]]);export{A as __pageData,c as default};
